import { Form } from '@base-ui/react/form';

it('controlled: typing clears server error', () => {
  function App() {
    const [v, setV] = React.useState('');
    return (
      <Form errors={{ message: 'Server error' }}>
        <Field.Root name="message">
          <Field.Control value={v} onValueChange={setV} />
          <Field.Error />
        </Field.Root>
      </Form>
    );
  }
  render(<App />);
  expect(screen.queryByText('Server error')).not.toBe(null);
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
  expect(screen.queryByText('Server error')).toBe(null);
});

it('controlled: programmatic set resolves required error after submit (onSubmit)', async () => {
  function App() {
    const [v, setV] = React.useState('');
    return (
      <Form>
        <Field.Root name="message">
          <Field.Control required value={v} onValueChange={setV} />
          <Field.Error match="valueMissing">Required</Field.Error>
        </Field.Root>
        <button type="button" onClick={() => setV('x')}>set</button>
        <button type="submit">submit</button>
      </Form>
    );
  }
  render(<App />);
  await act(async () => { fireEvent.click(screen.getByText('submit')); });
  expect(screen.queryByText('Required')).not.toBe(null);
  await act(async () => { fireEvent.click(screen.getByText('set')); });
  expect(screen.queryByText('Required')).toBe(null);
});

it('controlled: rejected value leaves field state untouched', () => {
  const validate = vi.fn(() => null);
  render(
    <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
      <Field.Control value="" onValueChange={() => {}} />
    </Field.Root>,
